rss.channel:
{{/* Was "{{.Title}} on {{.Site.Title}}", which rendered as "Anthony Kevins on
     Anthony Kevins" for the main feed. Only add the section prefix when it
     differs from the site title. */}}
{{ with .Title }}{{ if ne . $.Site.Title }}{{.}} on {{ end }}{{ end }}{{ .Site.Title }}
{{ .Permalink }}
Recent content {{ with .Title }}in {{.}} {{ end }}on {{ .Site.Title }}
Hugo -- Academic theme (https://github.com/HugoBlox/theme-academic-cv){{ with .Site.LanguageCode }}
{{.}}{{end}}{{ with .Site.Author.email }}
{{.}}{{ with $.Site.Author.name }} ({{.}}){{end}}{{end}}{{ with .Site.Author.email }}
{{.}}{{ with $.Site.Author.name }} ({{.}}){{end}}{{end}}{{ with .Site.Copyright }}
{{/* footer_section.html substitutes {year}; this did not, so the feed carried
     the literal placeholder. markdownify also decodes the © entity. */}}
{{ replace . "{year}" now.Year | markdownify | plainify }}{{end}}{{ if not .Date.IsZero }}
{{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}{{ end }}

{{ range first 15 .Data.Pages }}


  {{ .Title }}
  {{ .Permalink }}
  {{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}
  {{ with .Site.Author.email }}{{.}}{{ with $.Site.Author.name }} ({{.}}){{end}}{{end}}
  {{ .Permalink }}
  {{ .Content | html }}

{{ end }}
